ALTER TABLE src_wms.wms_inventory ADD COLUMN quality_status VARCHAR(16) NOT NULL DEFAULT 'AVAILABLE',ADD COLUMN frozen_qty DECIMAL(18,4) NOT NULL DEFAULT 0,ADD COLUMN received_date DATE NULL;
CREATE TABLE src_wms.wms_inventory_action(id BIGINT AUTO_INCREMENT PRIMARY KEY,action_no VARCHAR(32) UNIQUE,action_type VARCHAR(20),material_code VARCHAR(32),warehouse_code VARCHAR(32),location_code VARCHAR(32),batch_no VARCHAR(64),quantity DECIMAL(18,4),reason VARCHAR(500),source_no VARCHAR(32),operator VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE src_wms.wms_transfer(id BIGINT AUTO_INCREMENT PRIMARY KEY,transfer_no VARCHAR(32) UNIQUE,material_code VARCHAR(32),batch_no VARCHAR(64),quantity DECIMAL(18,4),from_warehouse VARCHAR(32),from_location VARCHAR(32),to_warehouse VARCHAR(32),to_location VARCHAR(32),status VARCHAR(20) DEFAULT 'DRAFT');
